mapper.select:
SELECT CASE WHEN count(*) > 0 THEN 1 ELSE 0 END AS existence
FROM bt_plat_bot_info
WHERE status_cd = '00A'
AND bot_code = #{dto.botCode}

  AND plat_bot_id != #{dto.platBotId}

SELECT CASE WHEN count(*) > 0 THEN 1 ELSE 0 END AS existence
FROM bt_plat_bot_info
WHERE status_cd = '00A'
AND bot_id = #{dto.botId}
AND owner_tenant_id = #{dto.ownerTenantId}

SELECT

FROM bt_plat_bot_info a
WHERE a.bot_id = #{botId}
  AND a.owner_tenant_id = #{ownerTenantId}
  AND a.status_cd = '00A'

SELECT * FROM (
SELECT MIN(a.auth_id) as platBotId, MAX(a.bot_icon) as bot_icon, MAX(b.bot_name) as bot_name, MAX(a.bot_desc) as bot_desc, a.bot_id, MAX(a.owner_tenant_id) as owner_tenant_id, MAX(a.auth_tenant_id) as auth_tenant_id, MAX(a.user_id) as user_id, MAX(a.catalog_item_id) as catalog_item_id, MAX(c.catalog_name) as catalog_name, MAX(t.tenant_name) as tenant_name, MAX(u.real_name) as "creatorName", MAX(u.user_name) as "creatorCode", NULL AS req_url, MAX(a.creator_id) as creator_id, 'platform' AS "botType", 'F' AS "isPlatformPublish", MAX(a.created_time) as created_time FROM bt_bot_auth a LEFT JOIN bt_bot b on a.bot_id = b.bot_id and b.tenant_id = a.owner_tenant_id and b.bot_status = '1' and b.status_cd = '00A' LEFT JOIN bt_catalog c on a.catalog_item_id = c.catalog_id LEFT JOIN bt_tenant t on t.tenant_id = a.owner_tenant_id LEFT JOIN bt_user u on u.user_id = a.creator_id WHERE a.status_cd = '00A' AND b.status_cd = '00A' AND b.bot_status = '1'
AND t.status_cd = '00A'
AND a.auth_status = 'T'
AND a.auth_tenant_id IN (#{query.tenantId}, -1) AND a.user_id IN (#{query.userId}, -1) AND a.org_id IN ( #{orgId} )
AND a.bot_name LIKE
#{query.searchContent}
AND a.catalog_item_id = #{query.catalogItemId}
AND (a.data_from != '10A' OR a.data_from IS NULL)
GROUP BY a.bot_id
UNION ALL
SELECT i.plat_bot_id, i.bot_icon AS bot_icon, i.bot_name, i.bot_desc, i.bot_id, i.owner_tenant_id, NULL AS auth_tenant_id, NULL AS user_id, i.catalog_item_id, d.catalog_name, NULL AS tenant_name, '平台' AS "creatorName", tu.user_name AS "creatorCode", i.req_url, i.creator_id, i.bot_type, 'T' AS "isPlatformPublish", i.created_time FROM bt_plat_bot_info i LEFT JOIN bt_catalog d on i.catalog_item_id = d.catalog_id and i.tenant_id = d.tenant_id LEFT JOIN bt_user tu on tu.user_id = i.creator_id LEFT JOIN bt_bot o ON i.bot_type = 'platform' AND i.bot_id = o.bot_id AND o.tenant_id = i.owner_tenant_id WHERE i.tenant_id = -1 AND i.status_cd = '00A' AND i.status = '1' AND (i.bot_type != 'platform' OR (o.status_cd = '00A' AND o.bot_status = '1'))
AND i.bot_name LIKE
#{query.searchContent}
AND i.catalog_item_id = #{query.catalogItemId}
) temp_result ORDER BY created_time DESC

SELECT * FROM ( SELECT a.bot_id, MIN(a.auth_id) as platBotId, MAX(b.bot_name) as bot_name, MAX(b.bot_use) as bot_use, MAX(a.owner_tenant_id) as owner_tenant_id, MAX(a.auth_tenant_id) as auth_tenant_id, MAX(a.catalog_item_id) as catalog_item_id, MAX(a.creator_id) as creator_id, MAX(a.created_time) as created_time FROM bt_bot_auth a JOIN bt_bot b on a.bot_id = b.bot_id and b.tenant_id = a.owner_tenant_id WHERE a.status_cd = '00A' AND b.status_cd = '00A' AND b.bot_status = '1' AND a.auth_status = 'T' AND a.data_from = '10A'
AND a.auth_tenant_id IN (#{query.tenantId}, -1) AND a.user_id IN (#{query.userId}, -1) AND a.org_id IN ( #{orgId} )
AND a.bot_name LIKE
#{query.searchContent}
AND a.catalog_item_id = #{query.catalogItemId}
GROUP BY a.bot_id ) temp_result ORDER BY created_time DESC
